{"claim": "The failure setter assigns its incoming parameter e into the closure-local error before clearing captures.", "pinned_revision": "2a343ed2a4ffbea73fb83862ee1e317662292481", "source_cards": "packages/zod/src/v4/core/parse.ts @ 2a343ed2a4ffbea73fb83862ee1e317662292481
65: export type $SafeParse = <T extends schemas.$ZodType>(
66:   schema: T,
67:   value: unknown,
68:   _ctx?: schemas.ParseContext<errors.$ZodIssue>
69: ) => util.SafeParseResult<core.output<T>>;
70: 
71: export const _safeParse: (_Err: $ZodErrorClass) => $SafeParse = (_Err) => (schema, value, _ctx) => {
72:   const ctx: schemas.ParseContextInternal = _ctx ? { ..._ctx, async: false } : { async: false };
73:   const result = schema._zod.run({ value, issues: [] }, ctx);
74:   if (result instanceof Promise) {
75:     throw new core.$ZodAsyncError();
76:   }
77: 
78:   return result.issues.length ? failure(_Err, result.issues, ctx) : ({ success: true, data: result.value } as any);
79: };
80: export const safeParse: $SafeParse = /* @__PURE__*/ _safeParse(errors.$ZodRealError);
81: 
82: // the error is built on the first read of `error`: finalizing the issues and constructing the instance is most of a failing parse, and a caller that only branches on `success` never pays it. a getter in the literal keeps this small; the alternative, one shared accessor descriptor plus a hidden state slot, reads ~15% faster but costs ~75 B gzipped in every bundle
83: function failure(Err: $ZodErrorClass, issues: errors.$ZodRawIssue[], ctx: schemas.ParseContextInternal): any {
84:   let error: errors.$ZodError | undefined;
85:   return {
86:     success: false,
87:     get error() {
88:       if (!error) {
89:         error = new Err(issues.map((iss) => util.finalizeIssue(iss, ctx, core.config())));
90:         // finalizeIssue drops `input`, so the built error holds nothing; keeping the raw issues past this point pins the parsed value for the life of the result
91:         issues = undefined as any;
92:         ctx = undefined as any;
93:       }
94:       return error;
95:     },
96:     set error(e: errors.$ZodError) {
97:       error = e;
98:       // a replacement makes the getter's branch unreachable, so the captures have to go here too
99:       issues = undefined as any;
100:       ctx = undefined as any;
101:     },
102:   };
103: }
104: 
105: export type $SafeParseAsync = <T extends schemas.$ZodType>(
106:   schema: T,
107:   value: unknown,
108:   _ctx?: schemas.ParseContext<errors.$ZodIssue>
109: ) => Promise<util.SafeParseResult<core.output<T>>>;
110: 
111: export const _safeParseAsync: (_Err: $ZodErrorClass) => $SafeParseAsync = (_Err) => async (schema, value, _ctx) => {
112:   const ctx: schemas.ParseContextInternal = _ctx ? { ..._ctx, async: true } : { async: true };
113:   let result = schema._zod.run({ value, issues: [] }, ctx);
114:   if (result instanceof Promise) result = await result;
115: 
116:   return result.issues.length ? failure(_Err, result.issues, ctx) : ({ success: true, data: result.value } as any);
117: };
118: 
119: export const safeParseAsync: $SafeParseAsync = /* @__PURE__*/ _safeParseAsync(errors.$ZodRealError);"}
